/* ===== 缩放占位：修复页面底部大片空白 ===== */

html,
body {
  margin: 0;
  padding: 0;
  width: 100%;
}

body {
  overflow-x: hidden;
}

.pc-scale-space {
  width: 100%;
  min-height: 1px;
  overflow: hidden;
}

/*
 * 使用 left + translate 居中。
 * 清除原来的自动外边距，避免两种居中方式叠加。
 */
.pc-wrap {
  margin: 0;
  left: 50%;
  transform: translateX(-50%) scale(var(--pc-scale, 1));
  transform-origin: top center;
}

/* ===== 评论区：允许左右切卡，也允许上下滚动 ===== */

.pc-rv-cards {
  touch-action: pan-x pan-y;
}

