.pc-rv-body {
  min-height: 0;
  overflow-y: auto;
  touch-action: pan-x pan-y;
  -webkit-overflow-scrolling: touch;

  /* 正文滚到顶或底后，允许继续带动外层页面 */
  overscroll-behavior-y: auto;
}
</style>
</head>

<body>

<div class="pc-scale-space" id="pcScaleSpace">
