var $$=function(s,r){return Array.prototype.slice.call((r||document).querySelectorAll(s));};
var byId=function(i){return document.getElementById(i);};

/* ===== 播客暗号：记住上次进入的单集 ===== */

var PODCAST_BOOKMARK_KEY = "rabbit_podcast_bookmark_v1";

function readPodcastBookmark() {
  try {
    var raw = sessionStorage.getItem(PODCAST_BOOKMARK_KEY);
    return raw ? JSON.parse(raw) : null;
  } catch (error) {
    return null;
  }
}

function writePodcastBookmark(bookmark) {
  try {
    if (bookmark) {
      sessionStorage.setItem(
        PODCAST_BOOKMARK_KEY,
        JSON.stringify(bookmark)
      );
    } else {
      sessionStorage.removeItem(PODCAST_BOOKMARK_KEY);
    }
  } catch (error) {
    /* 存储不可用时，仍允许正常切换开场白 */
  }
}

var podcastJumpBusy = false;

window.jumpPodcastEpisode = async function (episodeIndex) {
  if (podcastJumpBusy) {
    return false;
  }

  var episodes = Array.isArray(cfg.episodes) ? cfg.episodes : [];
  var episode = episodes[episodeIndex];

  if (!Number.isInteger(episodeIndex) || !episode) {
    return false;
  }

  podcastJumpBusy = true;

  var previousBookmark = readPodcastBookmark();

  /*
   * 切换开场白会卸载当前主页，所以先留下暗号。
   * 标题用于帮助识别；index 用于恢复原来的位置。
   */
  writePodcastBookmark({
    index: episodeIndex,
    title: episode.title || ""
  });

  try {
    var success = await window.jumpTo(episodeIndex + 1);

    if (!success) {
      writePodcastBookmark(previousBookmark);
    }

    return success;
  } finally {
    podcastJumpBusy = false;
  }
};

/* ===== 单集跳转：使用与 YouTube 相同的酒馆助手接口 ===== */

var openingSwitchBusy = false;

window.jumpTo = async function (targetIndex) {
  if (openingSwitchBusy) {
    return false;
  }

  /* 避免把空值、布尔值等误认为编号 0 */
  var validType =
    typeof targetIndex === "number" ||
    (
      typeof targetIndex === "string" &&
      targetIndex.trim() !== ""
    );

  var index = validType ? Number(targetIndex) : NaN;

  if (!Number.isInteger(index) || index < 0) {
    window.alert("这个入口还没有填写有效的开场白编号。");
    return false;
  }

  openingSwitchBusy = true;

  try {
    if (
      typeof getChatMessages !== "function" ||
      typeof setChatMessages !== "function"
    ) {
      throw new Error("当前页面无法使用酒馆助手的消息接口。");
    }

    /* 读取第一条消息及其全部候选开场白 */
    var messages = await getChatMessages("0", {
      include_swipes: true
    });

    var opening = Array.isArray(messages)
      ? messages[0]
      : null;

    if (!opening || !Array.isArray(opening.swipes)) {
      throw new Error("没有读取到第一条消息的候选开场白。");
    }

    var count = opening.swipes.length;

    if (index >= count) {
      window.alert(
        "找不到编号为 " + index + " 的开场白。\n" +
        (
          count > 0
            ? "当前可用编号为 0～" + (count - 1) + "。"
            : "当前没有可用的候选开场白。"
        )
      );

      return false;
    }

    if (opening.swipe_id === index) {
      return true;
    }

    /* 切换候选，并刷新对应消息 */
    await setChatMessages(
      [
        {
          message_id: opening.message_id,
          swipe_id: index
        }
      ],
      {
        refresh: "affected"
      }
    );

    return true;
  } catch (error) {
    console.error("[苹果播客 开场白切换]", error);

    window.alert(
      "这次没有完成开场白切换。\n" +
      (
        error && error.message
          ? error.message
          : "请查看控制台中的错误信息。"
      )
    );

    return false;
  } finally {
    openingSwitchBusy = false;
  }
};

