/* ===== Squircle（Figma 风格连续曲率，仅用于封面/插图/评论卡这类圆角矩形） ===== */
function toRad(d){return d*Math.PI/180;}
function squirclePath(w,h,cr,cs){
  var maxR=Math.min(w,h)/2;cr=Math.min(cr,maxR);
  if(cr<=0)return 'M0 0L'+w+' 0L'+w+' '+h+'L0 '+h+'Z';
  var bud=maxR,mx=bud/cr-1;
  if(mx<0.001)return 'M'+cr+' 0L'+(w-cr)+' 0A'+cr+' '+cr+' 0 0 1 '+w+' '+cr+'L'+w+' '+(h-cr)+'A'+cr+' '+cr+' 0 0 1 '+(w-cr)+' '+h+'L'+cr+' '+h+'A'+cr+' '+cr+' 0 0 1 0 '+(h-cr)+'L0 '+cr+'A'+cr+' '+cr+' 0 0 1 '+cr+' 0Z';
  cs=Math.min(cs,mx);
