/* ===== 返回播客：保留完整页面，只滚动外层聊天区域 ===== */

(function () {
  var bookmark = readPodcastBookmark();

  if (!bookmark || !Number.isInteger(bookmark.index)) {
    return;
  }

  var episodes = Array.isArray(cfg.episodes)
    ? cfg.episodes
    : [];

  var targetIndex = bookmark.index;

  /* 调整过单集排列时，尝试根据标题找回 */
  if (
    !episodes[targetIndex] ||
    episodes[targetIndex].title !== bookmark.title
  ) {
    targetIndex = episodes.findIndex(function (episode) {
      return episode.title === bookmark.title;
    });
  }

  if (targetIndex < 0 || !episodes[targetIndex]) {
    return;
  }

  var cancelled = false;

  function cancelRestore() {
    cancelled = true;
  }

  /* 用户已经开始操作时，不再自动调整位置 */
  window.addEventListener("touchstart", cancelRestore, {
    passive: true,
    once: true
  });

  window.addEventListener("wheel", cancelRestore, {
    passive: true,
    once: true
  });

  window.addEventListener("keydown", cancelRestore, {
    once: true
  });

  /*
   * 清除内部隐藏容器的滚动偏移。
   * 这些容器只负责缩放、裁切，不应该负责定位单集。
   */
  function resetInternalScroll() {
    var space = byId("pcScaleSpace");
    var wrap = document.querySelector(".pc-wrap");

    if (space) {
      space.scrollTop = 0;
      space.scrollLeft = 0;
    }

    if (wrap) {
      wrap.scrollTop = 0;
      wrap.scrollLeft = 0;
    }

    /* 嵌入酒馆时，也保持 iframe 自身在顶部 */
    if (window.parent !== window) {
      window.scrollTo({
        top: 0,
        left: 0,
        behavior: "instant"
      });
    }
  }

  /*
   * 从 iframe 向外找真正能上下滚动的区域。
   * 不调用 target.scrollIntoView()，避免滚动隐藏容器。
   */
  function scrollOuterChatTo(target) {
    var currentWindow = window;
    var targetTop = target.getBoundingClientRect().top;

    /* 单独用浏览器打开 HTML 时，直接滚动当前页面 */
    if (currentWindow.parent === currentWindow) {
      currentWindow.scrollBy({
        top: targetTop - 12,
        behavior: "instant"
      });

      return true;
    }

    while (currentWindow.parent !== currentWindow) {
      var frame;
      var parentWindow;

      try {
        frame = currentWindow.frameElement;
        parentWindow = currentWindow.parent;

        /* 检查是否允许访问父页面 */
        void parentWindow.document.documentElement;
      } catch (error) {
        return false;
      }

      if (!frame) {
        return false;
      }

      /*
       * 把单集的位置转换成父页面中的位置。
       * 同时考虑 iframe 自身可能存在的缩放和边框。
       */
      var frameRect = frame.getBoundingClientRect();

      var frameScale = frame.offsetHeight
        ? frameRect.height / frame.offsetHeight
        : 1;

      if (!Number.isFinite(frameScale) || frameScale <= 0) {
        frameScale = 1;
      }

      targetTop =
        frameRect.top +
        (frame.clientTop + targetTop) * frameScale;

      var parentDocument = parentWindow.document;
      var node = frame.parentElement;

      while (
        node &&
        node !== parentDocument.body &&
        node !== parentDocument.documentElement
      ) {
        var style = parentWindow.getComputedStyle(node);

        var canScroll =
          /^(auto|scroll|overlay)$/.test(style.overflowY) &&
          node.scrollHeight > node.clientHeight + 1;

        if (canScroll) {
          var nodeRect = node.getBoundingClientRect();

          var nodeScale = node.offsetHeight
            ? nodeRect.height / node.offsetHeight
            : 1;

          if (!Number.isFinite(nodeScale) || nodeScale <= 0) {
            nodeScale = 1;
          }

          var visibleTop =
            nodeRect.top + node.clientTop * nodeScale;

          node.scrollBy({
            top: (targetTop - visibleTop - 12) / nodeScale,
            behavior: "instant"
          });

          return true;
        }

        node = node.parentElement;
      }

      /* 到最外层仍没有独立滚动区，则滚动最外层页面 */
      if (parentWindow.parent === parentWindow) {
        parentWindow.scrollBy({
          top: targetTop - 12,
          behavior: "instant"
        });

        return true;
      }

      currentWindow = parentWindow;
    }

    return false;
  }

  function nextFrame() {
    return new Promise(function (resolve) {
      window.requestAnimationFrame(resolve);
    });
  }

async function restoreEpisodePosition() {
  var hosts = [];
  var stopped = false;

  function stopRestore() {
    stopped = true;
  }

  function cleanup() {
    hosts.forEach(function (host) {
      host.removeEventListener("pointerdown", stopRestore, true);
      host.removeEventListener("touchstart", stopRestore, true);
      host.removeEventListener("wheel", stopRestore, true);
      host.removeEventListener("keydown", stopRestore, true);
    });
  }

  /*
   * 查找包含当前播客 iframe 的 #chat。
   * 每一层都保留 iframe，供后面换算目标位置。
   */
  var frames = [];
  var chat = null;
  var current = window;

  try {
    while (true) {
      hosts.push(current);

      current.addEventListener("pointerdown", stopRestore, true);
      current.addEventListener("touchstart", stopRestore, {
        passive: true,
        capture: true
      });
      current.addEventListener("wheel", stopRestore, {
        passive: true,
        capture: true
      });
      current.addEventListener("keydown", stopRestore, true);

      if (current.parent === current) {
        break;
      }

      var frame = current.frameElement;
      var parentHost = current.parent;

      void parentHost.document.documentElement;

      if (!frame) {
        break;
      }

      frames.push(frame);

      /*
       * 只选择确实包住当前 iframe 的 #chat，
       * 避免误取宿主里其他同名或无关区域。
       */
      var candidate = frame.closest("#chat");

      if (candidate) {
        chat = candidate;

        hosts.push(parentHost);
        parentHost.addEventListener(
          "pointerdown", stopRestore, true
        );
        parentHost.addEventListener("touchstart", stopRestore, {
          passive: true,
          capture: true
        });
        parentHost.addEventListener("wheel", stopRestore, {
          passive: true,
          capture: true
        });
        parentHost.addEventListener(
          "keydown", stopRestore, true
        );

        break;
      }

      current = parentHost;
    }

    if (!chat) {
      console.warn("[播客恢复] 没有找到包含当前页面的 #chat。");
      return;
    }

    if (cancelled || stopped) {
      return;
    }

    if (typeof window.__expandAllEpisodes === "function") {
      window.__expandAllEpisodes();
    }

    applySquircle();

    if (typeof window.scalePodcast === "function") {
      window.scalePodcast();
    }

    await nextFrame();
    await nextFrame();

    var target = $$(".pc-ep")[targetIndex];

    if (!target || !target.isConnected) {
      return;
    }

    /*
     * 读取实时坐标。
     * target 的矩形已经包含播客自身的缩放，
     * 这里不能再乘一次 --pc-scale。
     */
    function measurePosition() {
      var top = target.getBoundingClientRect().top;
      var signature = [top];

      frames.forEach(function (frame) {
        var rect = frame.getBoundingClientRect();
        var scale = frame.offsetHeight
          ? rect.height / frame.offsetHeight
          : 1;

        top = rect.top + (frame.clientTop + top) * scale;

        signature.push(
          rect.top,
          rect.height,
          frame.clientHeight
        );
      });

      var chatRect = chat.getBoundingClientRect();
      var chatScale = chat.offsetHeight
        ? chatRect.height / chat.offsetHeight
        : 1;

      if (!Number.isFinite(chatScale) || chatScale <= 0) {
        chatScale = 1;
      }

      var visibleTop =
        chatRect.top + chat.clientTop * chatScale;

      /*
       * 保留顶部 12px 呼吸空间。
       * 使用绝对 scrollTop，而不是累计 scrollBy。
       */
      var desired =
        chat.scrollTop +
        (top - visibleTop - 12) / chatScale;

      signature.push(
        chatRect.top,
        chatRect.height,
        chat.scrollTop,
        chat.scrollHeight
      );

      return {
        desired: desired,
        signature: signature.map(function (value) {
          return Math.round(value);
        }).join(",")
      };
    }

    /*
     * 等布局稳定时只读取，不滚动。
     * 最多等 2.5 秒，连续 350ms 稳定后定位一次。
     */
    var started = performance.now();
    var stableSince = started;
    var previous = measurePosition();

    while (performance.now() - started < 2500) {
      await nextFrame();

      if (cancelled || stopped || !target.isConnected) {
        return;
      }

      var now = performance.now();
      var measured = measurePosition();

      if (measured.signature !== previous.signature) {
        previous = measured;
        stableSince = now;
        continue;
      }

      if (now - stableSince < 350) {
        continue;
      }

      var maximum = Math.max(
        0,
        chat.scrollHeight - chat.clientHeight
      );

      var destination = Math.max(
        0,
        Math.min(maximum, measured.desired)
      );

      chat.scrollTo({
        top: destination,
        behavior: "instant"
