      /*
       * 之后只记录结果，绝不再次调整滚动。
       * 若宿主随后移走页面，可据此继续诊断。
       */
      console.log("[播客恢复：已执行一次定位]", {
        episode: targetIndex + 1,
        title: episodes[targetIndex].title,
        desiredScrollTop: measured.desired,
        appliedScrollTop: chat.scrollTop,
        maximumScrollTop: maximum
      });

      return;
    }

    console.warn("[播客恢复] 布局仍在变化，本次未强制滚动。");
  } catch (error) {
    console.error("[播客恢复]", error);
  } finally {
    cleanup();
  }
}
  if (document.fonts && document.fonts.ready) {
