/* ===== 等比例缩放 + 同步实际占位高度 ===== */

(function () {
  "use strict";

  var wrap = document.querySelector(".pc-wrap");
  var space = document.getElementById("pcScaleSpace");

  if (!wrap || !space) {
    return;
  }

  var frameId = null;

  function updateScale() {
    frameId = null;

    /* 读取实际设计宽度，当前为 440px */
    var designWidth = wrap.offsetWidth;

    if (!designWidth) {
      return;
    }

    /*
     * 按所在容器的宽度计算。
     * 保留原版总共 20px 的左右留白。
     */
    var containerWidth =
      space.clientWidth || window.innerWidth;

    var availableWidth = Math.max(1, containerWidth - 20);

    var scale = Math.min(
      1,
      availableWidth / designWidth
    );

    wrap.style.setProperty("--pc-scale", String(scale));

    /*
     * transform 不会改变布局占位高度。
     * 由外层容器使用缩放后的高度，消除底部多余空白。
     */
    var scaledHeight = Math.ceil(
      wrap.offsetHeight * scale
    );

    var nextHeight = scaledHeight + "px";

    if (space.style.height !== nextHeight) {
      space.style.height = nextHeight;
    }
  }

  function scheduleScale() {
    if (frameId !== null) {
      return;
    }

    frameId = window.requestAnimationFrame(updateScale);
  }

  /* 保留可供其他代码调用的刷新函数 */
  window.scalePodcast = scheduleScale;

  updateScale();

  window.addEventListener("load", scheduleScale);
  window.addEventListener("resize", scheduleScale);

  /*
   * 展开简介、展开单集、字体加载等造成页面高度变化时，
   * 自动重新同步占位高度。
   */
  var resizeObserver = null;
  var mutationObserver = null;

  if (window.ResizeObserver) {
    resizeObserver = new ResizeObserver(scheduleScale);

    resizeObserver.observe(wrap);
    resizeObserver.observe(space);
  } else {
    /* 旧环境的内容变化兼容处理 */
    mutationObserver = new MutationObserver(scheduleScale);

    mutationObserver.observe(wrap, {
      subtree: true,
      childList: true,
      characterData: true,
      attributes: true,
      attributeFilter: ["class", "style", "src"]
    });
  }

  /* 捕获子图片的加载事件 */
  wrap.addEventListener("load", scheduleScale, true);

  if (document.fonts && document.fonts.ready) {
    document.fonts.ready.then(scheduleScale);
  }

  window.addEventListener("pagehide", function () {
    if (resizeObserver) {
      resizeObserver.disconnect();
    }

    if (mutationObserver) {
      mutationObserver.disconnect();
    }

    if (frameId !== null) {
      window.cancelAnimationFrame(frameId);
      frameId = null;
    }
  });

  window.addEventListener("pageshow", function () {
    if (resizeObserver) {
      resizeObserver.observe(wrap);
      resizeObserver.observe(space);
    }

    if (mutationObserver) {
      mutationObserver.observe(wrap, {
        subtree: true,
        childList: true,
        characterData: true,
        attributes: true,
        attributeFilter: ["class", "style", "src"]
      });
    }

    scheduleScale();
  });
})();

